import React from 'react';

export const POSTFLOW_LOGO_DATA_URI = 'data:image/jpeg;base64,';

export default function PostFlowLogo({ className = 'w-8 h-8 sm:w-9 sm:h-9', rounded = 'rounded-xl' }) {
  return (
    <img
      src={POSTFLOW_LOGO_DATA_URI}
      alt="PostFlow AI Logo"
      className={`object-cover shadow-md flex-shrink-0 ${rounded} ${className}`}
    />
  );
}
